function getBaseUrl() {
  if (process.env.VERCEL_URL) return `https://${process.env.VERCEL_URL}`;
  if (process.env.NEXT_PUBLIC_APP_URL) return process.env.NEXT_PUBLIC_APP_URL;
  return 'http://localhost:3000';
}

async function getDashboardData() {
  const baseUrl = getBaseUrl();
  try {
    const [analytics, notifications, settings] = await Promise.all([
      fetch(`${baseUrl}/api/analytics`).then((r) => r.json()),
      fetch(`${baseUrl}/api/notifications`).then((r) => r.json()),
      fetch(`${baseUrl}/api/settings`).then((r) => r.json())
    ]);

    return { analytics, notifications, settings };
  } catch {
    // Return mock data for build time or when APIs are unavailable
    return {
      analytics: { views: 0, visitors: 0 },
      notifications: [],
      settings: {}
    };
  }
}

export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData();

  return (
    <div>
      <h2>Dashboard Content</h2>

      <section>
        <h3>Analytics</h3>
        <pre>{JSON.stringify(analytics, null, 2)}</pre>
      </section>

      <section>
        <h3>Notifications</h3>
        <pre>{JSON.stringify(notifications, null, 2)}</pre>
      </section>

      <section>
        <h3>Settings</h3>
        <pre>{JSON.stringify(settings, null, 2)}</pre>
      </section>
    </div>
  );
}

